import static org.hamcrest.Matchers.is;
import static org.springframework.test.web.servlet.result.MockMvcResultMatchers.jsonPath;
import static org.springframework.test.web.servlet.result.MockMvcResultMatchers.status;

import org.junit.jupiter.api.Test;
import org.owasp.webgoat.container.plugins.LessonTest;
import org.springframework.test.web.servlet.request.MockMvcRequestBuilders;

public class ServersOrderByInjectionTest extends LessonTest {

  @Test
  public void orderByColumnShouldNotBeInjectable() throws Exception {
    // The column parameter is concatenated straight into the ORDER BY clause of a
    // prepared statement. A protected implementation would treat the value as opaque
    // and the injected boolean condition would have no effect, leaving the rows
    // ordered by id (webgoat-dev first). Because the value is injectable, the
    // condition is evaluated and the rows are ordered by hostname instead, so this
    // assertion fails.
    mockMvc
        .perform(
            MockMvcRequestBuilders.get("/SqlInjectionMitigations/servers")
                .param(
                    "column",
                    "(case when (select password from user_system_data where user_name='dave')"
                        + " = 'passW0rD' then hostname else id end)"))
        .andExpect(status().isOk())
        .andExpect(jsonPath("$[0].hostname", is("webgoat-dev")));
  }
}

